<script setup>import{ref,onMounted}from'vue';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const items=ref([]);onMounted(async()=>items.value=(await queryEntity('orders')).data.items)</script><template><div class="admin-page"><PageHeader title="订单管理" description="跟踪订单确认、方案、生产与交付状态"><el-button type="primary">新建订单</el-button></PageHeader><div class="work-surface"><div class="filter-bar"><el-input placeholder="订单号 / 客户" style="width:230px"/><el-select placeholder="全部阶段" style="width:140px"><el-option label="方案设计" value="方案设计"/><el-option label="生产中" value="生产中"/></el-select><el-button type="primary" plain>查询</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="订单号" min-width="160"/><el-table-column prop="customer" label="客户" width="100"/><el-table-column prop="project" label="项目名称" min-width="210"/><el-table-column prop="designer" label="设计师" width="100"/><el-table-column prop="stage" label="当前阶段" width="110"/><el-table-column prop="delivery" label="预计交付" width="120"/><el-table-column prop="amount" label="预算金额" width="110"/><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><router-link :to="`/orders/${row.id}`" style="color:var(--primary)">查看详情</router-link></template></el-table-column></el-table></div></div></div></template>
